import{_ as a}from"./chunks/pixhack_v3_157_large_default.DZuhqzuK.js";import{_ as l,C as r,c as o,o as s,j as i,G as n,al as d,a as c}from"./chunks/framework.D8UyiDWg.js";const v=JSON.parse('{"title":"CUAV Pixhack V3 (Discontinued)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/pixhack_v3.md","filePath":"ko/flight_controller/pixhack_v3.md"}'),h={name:"ko/flight_controller/pixhack_v3.md"};function p(u,t,m,f,k,b){const e=r("Badge");return s(),o("div",null,[t[0]||(t[0]=i("h1",{id:"cuav-pixhack-v3-discontinued",tabindex:"-1"},[c("CUAV Pixhack V3 (Discontinued) "),i("a",{class:"header-anchor",href:"#cuav-pixhack-v3-discontinued","aria-label":'Permalink to "CUAV Pixhack V3 (Discontinued)"'},"​")],-1)),n(e,{type:"info",text:"Discontinued"}),t[1]||(t[1]=d('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This flight controller has been <a href="./../flight_controller/autopilot_experimental.html">discontinued</a> and is no longer commercially available.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The CUAV <em>Pixhack V3</em> flight controller board is a flexible autopilot intended primarily for manufacturers of commercial systems.</p><p>The board is a variant of the SOLO Pixhawk<sup>®</sup> 2 (PH2) flight controller, which is in turn based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS, and is fully compatible with both PX4 or ArduPilot<sup>®</sup> (APM) firmware.</p><p><em>Pixhack V3</em> has significant improvements with respect to the original design, including better interface layout and the addition of vibration damping and a thermostat system.</p><p><img src="'+a+'" alt="Pixhack v3"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h2 id="요약" tabindex="-1">요약 <a class="header-anchor" href="#요약" aria-label="Permalink to &quot;요약&quot;">​</a></h2><ul><li>마이크로 프로세서: <ul><li>STM32F427</li><li>STM32F100 (오류복구 코프로세서)</li></ul></li><li>센서: <ul><li>가속도계 (3): LS303D, MPU6000, MPU9250/hmc5983</li><li>자이로스코프 (3): L3GD20, MPU6000, MPU9250</li><li>나침반 (2): LS303D, MPU9250</li><li>기압계 (2): MS5611 X2</li></ul></li><li>인터페이스: <ul><li>MAVLink UART (2)</li><li>GPS UART (2)</li><li>디버그 UART (1)</li><li>RC 입력(PPM, SBUS, DSM/DSM2 용)</li><li>RSSI 입력: PWM 또는 3.3ADC</li><li>I2C (2)</li><li>CAN 버스 (1)</li><li>ADC 입력: 3.3V X1 , 6.6V X1</li><li>PWM 출력: 8 PWM IO + 4 IO</li></ul></li><li>전원시스템 <ul><li>PM 전원 입력: 4.5 ~ 5.5V</li><li>USB 전원 입력: 5.0V +- 0.25v</li></ul></li><li>중량과 크기 <ul><li>중량: 63g</li><li>폭: 68mm</li><li>두께: 17mm</li><li>길이: 44mm</li></ul></li><li>기타 특성: <ul><li>작동 온도: -20 ~ 60°c</li></ul></li></ul><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>보드는 아래에서 구입할 수 있습니다.</p><ul><li><a href="https://leixun.aliexpress.com/store" target="_blank" rel="noreferrer">leixun.aliexpress.com/store</a></li></ul><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v3_default</span></span></code></pre></div><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO 디버그</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (흐름 제어)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (흐름 제어)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td></td><td>콘솔</td></tr><tr><td>UART8</td><td></td><td>SERIAL4</td></tr></tbody></table>',18))])}const P=l(h,[["render",p]]);export{v as __pageData,P as default};
